"""Scaffold templates for ``brain init``.

Stored as module-level strings (not separate files) to keep the package
layout flat and avoid ``importlib.resources`` plumbing. If templates grow
beyond half a dozen, move them to ``central_brain/cli/templates/``.
"""

from __future__ import annotations

from string import Template

BRAIN_YAML = Template(
    """\
# $name — generated by `brain init`
name: $name
version: 0.1.0

capabilities:
  - memory
  - decisions
  - reflection

# Default workspace is ./data — uncomment to override.
# workspace:
#   data_dir: ./custom-data

# HSAM is enabled by default; writes daily markdown archives under
# data_dir/hsam/. Set enabled: false to opt out.
# memory:
#   hsam:
#     enabled: true
#     subdir: hsam
"""
)

CLAUDE_MD = Template(
    """\
# $name

An AI agent built on [central-brain](https://github.com/xy-claude/central-brain).

## Role

<!-- Describe what this agent does. -->

## Persistent memory

This agent's state lives in `data/brain.db`. See `brain.yaml` for configuration.

Capabilities available through the `Agent` API:

- `remember(content, kind, tags, metadata)` — structured facts (dedup-safe)
- `recall(query)` — FTS5-ranked retrieval
- `decide(action, reversible, risk, confidence, reasoning)` — classified decision log
- `reverse(decision_id)` / `complete(decision_id)` — state transitions
- `log_event(event_type, payload)` — append-only event log
- `append_today(text)` — HSAM daily markdown archive
- `gather_context()` + `template_summary()` — end-of-session reflection

## Session lifecycle

```python
from central_brain import Agent

with Agent.from_config("./brain.yaml") as agent:
    agent.start_session("session-id")
    # ... agent does its work, calling remember / decide / log_event ...
    agent.save_reflection(what_went_well="...", apply_next_session="...")
    agent.end_session()
```
"""
)

MCP_JSON = Template(
    """\
{
  "mcpServers": {
    "central-brain": {
      "command": "brain",
      "args": ["serve", "."]
    }
  }
}
"""
)

GITIGNORE = Template(
    """\
# central-brain state (live data, not source)
data/
logs/

# Python
__pycache__/
*.py[cod]
*.egg-info/
.venv/
venv/

# OS
.DS_Store
"""
)
